//! Module containing [`ServoPlayerGenerated`], the sample struct type generated by the
//! [`servo_player!`](macro@crate::servo::servo_player) macro.
//!
//! Every item on the sample pages is the macro's own output for the declaration in this
//! file, so the pages show exactly what a declaration generates.

// Docs build only: a servo claims its LEDC timer and channel with link-level symbols, so a
// sample compiled into the library would collide with a user's servo on the same timer.
#[cfg(doc)]
use crate::servo::servo_player;

#[cfg(doc)]
servo_player! {
    pub ServoPlayerGenerated { pin: GPIO4, timer: Timer0, channel: Channel0 }
}
